preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0 .75rem;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-width: 0;
}
.risu-chat > div > div {
  width: 100%;
  min-width: 0;
  margin: auto;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsy-font-size로 바꿉니다. */
.rtmsy {
  --rtmsy-bg-fill: transparent;
  --rtmsy-bg-border: 0;
  --rtmsy-blur: none;
  --rtmsy-bg-edge: none;
  --rtmsy-bg-sheen: linear-gradient(transparent, transparent);
  --rtmsy-bg-fallback: transparent;
  --rtmsy-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsy-font-size: 15.5px;
  --rtmsy-line-height: 1.75;
  --rtmsy-para-gap: .75em;
  --rtmsy-dialog-weight: 600;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsy {
  --risu-font-family: var(--rtmsy-font-body);
  --FontColorStandard: var(--rtmsy-ink);
  --FontColorBold: var(--rtmsy-strong, var(--rtmsy-ink));
  --FontColorItalic: var(--rtmsy-muted);
  --FontColorItalicBold: var(--rtmsy-muted);
  --FontColorQuote1: var(--rtmsy-muted);
  --FontColorQuote2: var(--rtmsy-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsy-ink);
  font-family: var(--rtmsy-font-body);
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
  letter-spacing: var(--rtmsy-tracking, -.005em);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.rtmsy, .rtmsy *, .rtmsy *::before, .rtmsy *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsy.rtmsy { display: block; }
.rtmsy ::selection { background: color-mix(in srgb, var(--rtmsy-accent) 26%, transparent); color: inherit; }
.rtmsy__content {
  min-width: 0;
  color: var(--rtmsy-ink);
  word-break: keep-all;
  overflow-wrap: break-word;
  text-wrap: pretty;
}
.rtmsy__content .chattext {
  --tw-prose-code: var(--rtmsy-strong, var(--rtmsy-ink));
  --tw-prose-pre-code: var(--rtmsy-ink);
  --tw-prose-pre-bg: var(--rtmsy-tint);
  max-width: none;
  color: var(--rtmsy-ink);
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
}
/* :where()로 우선순위를 낮춰 캐릭터 카드 자체 HTML 스타일이 이기게 합니다. */
.rtmsy__content :where(p, li, td, th, blockquote) {
  font-size: var(--rtmsy-font-size);
  line-height: var(--rtmsy-line-height);
}
.rtmsy__content :where(p) { margin: 0 0 var(--rtmsy-para-gap); }
.rtmsy__content :where(p:last-child) { margin-bottom: 0; }
.rtmsy__content :where(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsy-font-display);
  margin: 1.35em 0 .55em;
  color: var(--rtmsy-strong, var(--rtmsy-ink));
  font-family: var(--rtmsy-font-display);
  line-height: 1.35;
  letter-spacing: -.015em;
  font-weight: 700;
}
.rtmsy__content :where(h1, h2, h3, h4, h5, h6):where(:first-child) { margin-top: .15em; }
.rtmsy__content :where(h1) { font-size: calc(var(--rtmsy-font-size) * 1.55); }
.rtmsy__content :where(h2) { font-size: calc(var(--rtmsy-font-size) * 1.32); }
.rtmsy__content :where(h3) { font-size: calc(var(--rtmsy-font-size) * 1.15); }
.rtmsy__content :where(h4, h5, h6) { font-size: var(--rtmsy-font-size); color: var(--rtmsy-muted); }
.rtmsy__content :where(strong) { font-weight: 700; color: var(--rtmsy-strong, var(--rtmsy-ink)); }
/* 한글은 기울임 글꼴이 없어 가짜 기울임 대신 색으로만 구분합니다. */
.rtmsy__content :where(em) { font-style: normal; color: var(--rtmsy-muted); }
.rtmsy__content mark[risu-mark="quote1"],
.rtmsy__content mark[risu-mark="blockquote1"] { color: var(--rtmsy-muted); background: transparent; }
.rtmsy__content mark[risu-mark="quote2"],
.rtmsy__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsy-dialog);
  font-weight: var(--rtmsy-dialog-weight);
  background: transparent;
}
.rtmsy__content :where(blockquote) {
  margin: 1em 0;
  padding: .55em 1.05em;
  border-left: 2.5px solid var(--rtmsy-accent);
  border-radius: 0 .5rem .5rem 0;
  background: var(--rtmsy-tint);
  color: var(--rtmsy-muted);
}
.rtmsy__content :where(ul, ol) { margin: .85em 0; padding-left: 1.45em; }
.rtmsy__content :where(li) { margin: .28em 0; padding-left: .12em; color: var(--rtmsy-ink); }
.rtmsy__content :where(li)::marker { color: var(--rtmsy-accent); }
.rtmsy__content :where(a) {
  color: var(--rtmsy-accent);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--rtmsy-accent) 45%, transparent);
  text-underline-offset: 3px;
}
.rtmsy__content :where(a:hover) { text-decoration-color: currentColor; }
.rtmsy__content :where(hr) {
  height: 1px;
  border: 0;
  margin: 1.55em 0;
  background: linear-gradient(90deg, transparent, var(--rtmsy-line) 15%, var(--rtmsy-line) 85%, transparent);
}
.rtmsy__content :where(code) {
  --risu-font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  padding: .12em .38em;
  border-radius: .3em;
  color: var(--rtmsy-strong, var(--rtmsy-ink));
  background: var(--rtmsy-tint);
  font-family: "IBM Plex Mono", "JetBrains Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsy-font-size) * .88);
  line-height: 1.5;
}
.rtmsy__content :where(pre) {
  max-width: 100%;
  overflow-x: auto;
  margin: 1em 0;
  padding: .9em 1.05em;
  color: var(--rtmsy-ink);
  background: var(--rtmsy-tint);
  border: 1px solid var(--rtmsy-line);
  border-radius: .5rem;
  font-size: calc(var(--rtmsy-font-size) * .88);
  line-height: 1.55;
}
.rtmsy__content :where(pre code) { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsy__content :where(table) {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsy__content :where(th, td) {
  padding: .52em .78em;
  color: var(--rtmsy-ink);
  border-bottom: 1px solid var(--rtmsy-line);
  text-align: left;
  vertical-align: top;
}
.rtmsy__content :where(th) {
  background: var(--rtmsy-tint);
  color: var(--rtmsy-strong, var(--rtmsy-ink));
  font-weight: 600;
}
.rtmsy__content :where(img) { display: block; max-width: 100%; height: auto; margin: .75em auto; border-radius: .55rem; }
.rtmsy__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 6rem;
  padding: .75rem .9rem;
  resize: vertical;
  color: var(--rtmsy-ink) !important;
  background: var(--rtmsy-edit-bg) !important;
  border: 1px solid var(--rtmsy-line);
  border-radius: .55rem;
  font: inherit;
  font-size: var(--rtmsy-font-size) !important;
  line-height: var(--rtmsy-line-height) !important;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.rtmsy__content textarea.message-edit-area:focus {
  outline: none;
  border-color: var(--rtmsy-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--rtmsy-accent) 18%, transparent);
}

/* 조작부: 생성 정보와 Risu 기본 버튼만 다듬고, 서드파티 플러그인 버튼 모양은 유지합니다. */
.rtmsy__footer {
  --risu-theme-textcolor2: var(--rtmsy-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
  color: var(--rtmsy-muted);
}
.rtmsy__info, .rtmsy__actions { min-width: 0; max-width: 100%; }
.rtmsy__info > div, .rtmsy__actions > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .25rem; }
.rtmsy__actions > div > div { display: flex; flex-wrap: wrap; align-items: center; min-width: 0; gap: .05rem; }
.rtmsy__info button.transition-all,
.rtmsy__actions button[class*="button-icon-"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  min-width: 1.9rem;
  min-height: 1.9rem;
  padding: .28rem;
  border-radius: 999px;
  background: transparent;
  transition: background-color .15s ease, color .15s ease;
}
.rtmsy__info button.transition-all:hover,
.rtmsy__actions button[class*="button-icon-"]:hover { background: var(--rtmsy-tint); color: var(--rtmsy-ink); }
.rtmsy__info button:not(.transition-all) {
  background: transparent;
  color: inherit;
  border: 1px solid var(--rtmsy-line);
  padding: .18rem .5rem;
  border-radius: .35rem;
  font-size: .92em;
  transition: background-color .15s ease, color .15s ease;
}
.rtmsy__info button:not(.transition-all):hover { background: var(--rtmsy-tint); color: var(--rtmsy-ink); }
.rtmsy :where(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsy-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsy__portrait { overflow: hidden; background: var(--rtmsy-tint); }
.rtmsy__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

@media (prefers-reduced-motion: reduce) {
  .rtmsy, .rtmsy * { transition: none !important; animation: none !important; }
}
@media (prefers-reduced-transparency: reduce) {
  .rtmsy .rtmsy__bg {
    background: var(--rtmsy-bg-fallback, var(--rtmsy-bg-fill));
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .rtmsy .rtmsy__bg { background: var(--rtmsy-bg-fallback, var(--rtmsy-bg-fill)); }
}

.rtmsy__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsy-bg-fill);
  border: var(--rtmsy-bg-border, 0);
  -webkit-backdrop-filter: var(--rtmsy-blur);
  backdrop-filter: var(--rtmsy-blur);
  box-shadow: var(--rtmsy-bg-edge);
}

/* 구조: 메신저 양쪽 */


.rtmsy {
  --rtmsy-col: 44rem;
  --rtmsy-gap: clamp(1rem, 2.2vw, 1.8rem);
  --rtmsy-edge: 1rem;
  --rtmsy-fixed-bottom: 5rem;
  --rtmsy-fixed-w: max(8rem, min(calc((100% - var(--rtmsy-col)) / 2 - var(--rtmsy-gap) - var(--rtmsy-edge)), calc((100vh - var(--rtmsy-edge) - var(--rtmsy-fixed-bottom)) * 3 / 4)));
  --rtmsy-pad: .65rem;
  max-width: var(--rtmsy-col);
  margin: 0 auto;
  padding: .55rem 0;
}
.rtmsy__side { display: none; }
.rtmsy__main { position: relative; min-width: 0; }
.rtmsy__speaker {
  display: flex;
  align-items: center;
  gap: .45rem;
  margin-bottom: .55rem;
  color: var(--rtmsy-muted);
  font-size: .82em;
  font-weight: 700;
  letter-spacing: .02em;
}
.rtmsy--char .rtmsy__speaker { color: var(--rtmsy-strong, var(--rtmsy-ink)); }
.rtmsy .x-risu-rtmsy-pair { display: block !important; height: 0; margin: 0; padding: 0; }
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
  display: none;
  background-size: cover;
  background-position: center 22%;
}
.rtmsy .x-risu-rtmsy-fade { display: none; }

/* 고정 초상이 채팅 영역을 기준으로 놓이게 합니다 (이 테마가 채팅에 있을 때만 걸립니다). */
:has(> .default-chat-screen .rtmsy) { transform: translateZ(0); }

/* PC: 1040px 이상에서만 양옆 고정 초상을 띄우고 가운데 열과 겹치지 않게 폭을 확보합니다. */
@media (min-width: 1040px) {
  .rtmsy { --rtmsy-col: min(44rem, calc(100% - 22rem)); }
  .chat-message-container:first-child .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user),
  .flex-col-reverse:empty + .risu-chat .rtmsy :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    display: block;
    position: fixed;
    z-index: 1;
    top: var(--rtmsy-edge);
    bottom: var(--rtmsy-fixed-bottom);
    margin-block: auto;
    width: var(--rtmsy-fixed-w);
    aspect-ratio: 3 / 4;
    transition: opacity .3s ease, filter .3s ease, translate .3s ease, scale .3s ease;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-char {
    left: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-char));
    anchor-name: --rtmsy-portrait-char;
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-pair-user {
    right: var(--rtmsy-edge);
    transform: rotate(var(--rtmsy-tilt-user));
  }
  .chat-message-container:first-child .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--char .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child .rtmsy--user .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--user .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy--user .x-risu-rtmsy-pair-user {
    translate: 0 -4px;
    scale: 1.018;
    filter: drop-shadow(0 16px 14px rgba(0, 0, 0, .24));
  }
  .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
  .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
    display: block;
    position: fixed;
    z-index: 2;
    top: calc(var(--rtmsy-edge) + .6rem);
    left: calc(var(--rtmsy-edge) + .6rem);
    margin: 0;
  }
  @supports (anchor-name: --a) {
    .chat-message-container:first-child .rtmsy .x-risu-rtmsy-fade,
    .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy .x-risu-rtmsy-fade,
    .flex-col-reverse:empty + .risu-chat .rtmsy .x-risu-rtmsy-fade {
      position-anchor: --rtmsy-portrait-char;
      top: calc(anchor(top) + .6rem);
      left: calc(anchor(left) + .6rem);
    }
  }
  .rtmsy .x-risu-rtmsy-fade > summary {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 50%;
    list-style: none;
    cursor: pointer;
    color: #fff;
    font-size: .95rem;
    line-height: 1;
    background: rgba(0, 0, 0, .34);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .28);
    opacity: .72;
    transition: opacity .2s ease, background .2s ease;
    user-select: none;
  }
  .rtmsy .x-risu-rtmsy-fade > summary::-webkit-details-marker { display: none; }
  .rtmsy .x-risu-rtmsy-fade > summary::before { content: "◐"; }
  .rtmsy .x-risu-rtmsy-fade > summary:hover,
  .rtmsy .x-risu-rtmsy-fade[open] > summary { opacity: 1; background: rgba(0, 0, 0, .54); }
  .rtmsy.rtmsy .x-risu-rtmsy-pair.x-risu-rtmsy-pair:has(> .x-risu-rtmsy-fade[open]) :is(.x-risu-rtmsy-pair-char, .x-risu-rtmsy-pair-user) {
    opacity: .08;
    translate: none;
    scale: none;
    filter: none;
  }
}

/* 휴대폰·좁은 창: 메시지마다 위에 두 초상이 마주 보고, 반대편 초상이 빈 액자 위에 정확히 겹칩니다. */
@media (max-width: 1039px) {
  .rtmsy.rtmsy { display: grid; }
  .rtmsy {
    --rtmsy-side-w: clamp(4.6rem, 16vw, 6rem);
    --rtmsy-row-gap: .85rem;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    row-gap: var(--rtmsy-row-gap);
    column-gap: .6rem;
    max-width: none;
    padding: var(--rtmsy-pad) 0;
  }
  .rtmsy__side { display: flex; flex-direction: row; align-items: center; gap: .55rem; min-width: 0; }
  .rtmsy__side--char { grid-column: 1; grid-row: 1; justify-content: flex-start; }
  .rtmsy__side--user { grid-column: 2; grid-row: 1; flex-direction: row-reverse; justify-content: flex-start; }
  .rtmsy__frame { position: relative; width: var(--rtmsy-side-w); flex: 0 0 auto; aspect-ratio: 3 / 4; }
  .rtmsy__portrait { width: 100%; height: 100%; border-radius: inherit; }
  .rtmsy__side-name { min-width: 0; color: var(--rtmsy-muted); font-size: .78em; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .rtmsy__main { grid-column: 1 / -1; grid-row: 2; min-width: 0; max-width: 100%; }
  .rtmsy__speaker { display: none; }
  .rtmsy--char .rtmsy__side--char .rtmsy__side-name, .rtmsy--user .rtmsy__side--user .rtmsy__side-name { color: var(--rtmsy-strong, var(--rtmsy-ink)); }
  .rtmsy--char .rtmsy__side--char .rtmsy__frame, .rtmsy--user .rtmsy__side--user .rtmsy__frame {
    translate: 0 -3px;
    scale: 1.04;
    filter: drop-shadow(0 8px 8px rgba(0, 0, 0, .22));
  }
  .rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
    position: absolute;
    z-index: 2;
    bottom: calc(100% + var(--rtmsy-row-gap) + 1px);
    width: var(--rtmsy-side-w);
    aspect-ratio: 3 / 4;
  }
  .rtmsy--user .x-risu-rtmsy-pair-char { display: block; left: 0; }
  .rtmsy--char .x-risu-rtmsy-pair-user { display: block; right: 0; }
}
.rtmsy { --rtmsy-tilt-char: 0deg; --rtmsy-tilt-user: 0deg; }
.rtmsy__frame {
  border-radius: .95rem;
  background: var(--rtmsy-tint);
  box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 6px 16px var(--rtmsy-shadow);
}
.rtmsy .x-risu-rtmsy-pair-char, .rtmsy .x-risu-rtmsy-pair-user {
  border-radius: 1rem;
  box-shadow: 0 0 0 1px var(--rtmsy-frame), 0 12px 28px var(--rtmsy-shadow);
}
@media (min-width: 1040px) {
  .chat-message-container:first-child .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--char .x-risu-rtmsy-pair-char,
  .flex-col-reverse:empty + .risu-chat .rtmsy--char .x-risu-rtmsy-pair-char,
  .chat-message-container:first-child .rtmsy--user .x-risu-rtmsy-pair-user,
  .chat-message-container:first-child:not(:has(.x-risu-rtmsy-pair)) + .chat-message-container .rtmsy--user .x-risu-rtmsy-pair-user,
  .flex-col-reverse:empty + .risu-chat .rtmsy--user .x-risu-rtmsy-pair-user {
    box-shadow: 0 0 0 1.5px var(--rtmsy-accent), 0 16px 34px var(--rtmsy-shadow);
  }
}
.rtmsy__main {
  padding: 1.05rem 1.25rem .85rem;
  border: 1px solid var(--rtmsy-line);
  border-radius: 1rem;
  box-shadow: 0 8px 22px var(--rtmsy-shadow);
}
.rtmsy .rtmsy__bg { background: var(--rtmsy-bg-sheen), var(--rtmsy-panel); }
.rtmsy--user .rtmsy__bg { background: var(--rtmsy-bg-sheen), var(--rtmsy-panel-user); }
.rtmsy__speaker {
  padding-bottom: .45rem;
  border-bottom: 1px solid var(--rtmsy-line);
}
.rtmsy__speaker::before {
  content: "";
  width: .42rem;
  height: .42rem;
  border-radius: 50%;
  background: var(--rtmsy-accent);
  flex: none;
}
.rtmsy__footer { margin-top: .75rem; padding-top: .5rem; border-top: 1px solid var(--rtmsy-line); font-size: .85em; }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (갈색) ── */
.rtmsy {
  --rtmsy-wall: #27201c;
  --rtmsy-panel: #332a24;
  --rtmsy-panel-user: #3b312a;
  --rtmsy-ink: #ebe2d7;
  --rtmsy-strong: #fbf6ee;
  --rtmsy-muted: #b2a392;
  --rtmsy-accent: #caa77b;
  --rtmsy-dialog: #ebd0a6;
  --rtmsy-frame: #4a3d34;
  --rtmsy-shadow: rgba(0, 0, 0, .3);
  --rtmsy-line: #483b32;
  --rtmsy-tint: #3e332c;
  --rtmsy-edit-bg: #2d2520;
}
